#!/usr/bin/env python3
"""
Manchester editor: every Mutate menu item re-translates the peptide above the track and says what changed
(e.g. "premature stop at residue 3 (E3*)"). Also fixes "Mutate track sequence", which passed the variant's
phase instead of the variant.

    sudo python3 install-mutate-reorf.py /opt/baja-apps

Writes baja/bio/orfs/refresh-orf-after-mutation.js and edits snp-menu.js, menu-factory.js and
mouse-over-highlight.js (each backed up as <file>.before-mutate-reorf). Refuses, changing nothing, if a file
does not contain the expected code. Safe to run twice.
"""
import os, shutil, sys
OPS = {'baja/manchester/menu/snp-menu.js': [('                    CurrentLayout.clearComponent(\'buttonMenuPanel|labelPanel\')\n                    const hl = await exec(\'baja/manchester/menu/variant-tools-finder.js\', graph)\n                    CurrentLayout.clearComponent(\'buttonMenuPanel|labelPanel\')\n                    CurrentLayout.setComponent(\'buttonMenuPanel\', hl);\n                    track.mutateTrackWithSingleMutation(snp)\n                    track.generateORF();\n                    infoPrompt(" Track sequence has changed. ")\n                },\n                move: () => {\n                }\n', '                    CurrentLayout.clearComponent(\'buttonMenuPanel|labelPanel\')\n                    const hl = await exec(\'baja/manchester/menu/variant-tools-finder.js\', graph)\n                    CurrentLayout.clearComponent(\'buttonMenuPanel|labelPanel\')\n                    CurrentLayout.setComponent(\'buttonMenuPanel\', hl);\n                    const __pepBefore = track.orf && track.orf.sequence;\n                    track.mutateTrackWithSingleMutation(snp)\n                    // Re-translate the peptide above the track (if it has one) and say what it did.\n                    await exec(\'baja/bio/orfs/refresh-orf-after-mutation.js\', track, graph, __pepBefore);\n                    infoPrompt(" Track sequence has changed. ")\n                },\n                move: () => {\n                }\n')], 'baja/manchester/menu/menu-factory.js': [("                },\n                {\n                    label: 'Mutate track sequence',\n                    click: async (xwc, ywc) => {\n                        selectedTrack.mutateTrackWithSingleMutation(snpindel.phase)\n                    },\n                    move: () => {\n                        log('')\n                    }\n", "                },\n                {\n                    label: 'Mutate track sequence',\n                    click: async (xwc, ywc) => {\n                        // the variant itself (this used to pass its phase, which is not a mutation)\n                        const __pepBefore = selectedTrack.orf && selectedTrack.orf.sequence;\n                        try { graph.pushOntoHistory(); } catch (e) { }\n                        selectedTrack.mutateTrackWithSingleMutation(snpindel)\n                        await exec('baja/bio/orfs/refresh-orf-after-mutation.js', selectedTrack, graph, __pepBefore);\n                    },\n                    move: () => {\n                        log('')\n                    }\n")], 'baja/manchester/menu/mouse-over-highlight.js': [("\n\n                                    setTimeout(async () => {\n                                        graph.pushOntoHistory()\n                                        for (let snp of snpsv) {\n                                            selectedTrack.resolveSNP(snp)\n                                        }\n                                    })\n                                }\n                            },\n                                {\n                                    label: '',\n                                    click: async () => {\n                                        setTimeout(async () => {\n                                            graph.pushOntoHistory()\n                                            for (let snp of snpsv) {\n                                                selectedTrack.resolveSNP(snp)\n                                            }\n                                        })\n                                    }\n                                })\n                        }\n", "\n\n                                    setTimeout(async () => {\n                                        graph.pushOntoHistory()\n                                        const __pepBefore = selectedTrack.orf && selectedTrack.orf.sequence;\n                                        for (let snp of snpsv) {\n                                            selectedTrack.resolveSNP(snp)\n                                        }\n                                        await exec('baja/bio/orfs/refresh-orf-after-mutation.js', selectedTrack, graph, __pepBefore);\n                                    })\n                                }\n                            },\n                                {\n                                    label: '',\n                                    click: async () => {\n                                        setTimeout(async () => {\n                                            graph.pushOntoHistory()\n                                            const __pepBefore = selectedTrack.orf && selectedTrack.orf.sequence;\n                                            for (let snp of snpsv) {\n                                                selectedTrack.resolveSNP(snp)\n                                            }\n                                            await exec('baja/bio/orfs/refresh-orf-after-mutation.js', selectedTrack, graph, __pepBefore);\n                                        })\n                                    }\n                                })\n                        }\n")]}
MODULES = {'baja/bio/orfs/refresh-orf-after-mutation.js': 'function (track, graph, before) {\n\n    // RE-TRANSLATE AFTER A MUTATION. Every "Mutate" path calls this once the track\'s sequence has\n    // changed, so the peptide drawn above the track is the peptide of the sequence now on it.\n    //\n    //   const before = track.orf && track.orf.sequence;      // capture first\n    //   ... mutate ...\n    //   await exec(\'baja/bio/orfs/refresh-orf-after-mutation.js\', track, graph, before)\n    //\n    // Only a track that HAS a peptide is re-translated: one with an ORF already, or with CDS /\n    // Translation annotations to build one from. track.updateCDS() (which the mutators call) skips\n    // any track without both a TSS and a STOP annotation, and the Mutate menus did not all call\n    // generateORF themselves, so a peptide could survive the edit unchanged.\n    //\n    // Resolves { changed, before, after, summary } and says what happened to the protein.\n    return (async () => {\n        const has = () => {\n            if (track && track.orf && track.orf.sequence) return true;\n            return (track && track.annotations || []).some((a) => {\n                const t = (\'\' + (a && a.type)).toLowerCase();\n                return t === \'cds\' || t === \'translation\';\n            });\n        };\n        if (!track || typeof track.generateORF !== \'function\' || !has()) return { changed: false };\n        const was = (before != null) ? (\'\' + before) : \'\';\n        try { track.generateORF(); } catch (e) { }\n        const now = (track.orf && track.orf.sequence) ? (\'\' + track.orf.sequence) : \'\';\n        try { if (graph && graph.wake) graph.wake(); } catch (e) { }\n\n        // What changed, in protein terms: the first residue that differs.\n        let summary = \'\';\n        if (was && now && was !== now) {\n            let i = 0;\n            while (i < was.length && i < now.length && was[i] === now[i]) i++;\n            const pos = i + 1;\n            if (now.length < was.length && now.length === i) {\n                summary = \'premature stop at residue \' + pos + \' (\' + was[i] + pos + \'*), protein \' + now.length + \' aa (was \' + was.length + \')\';\n            } else if (now.length !== was.length) {\n                summary = \'protein changes from residue \' + pos + \' (\' + was[i] + pos + (now[i] || \'?\') + \'), protein \' + now.length + \' aa (was \' + was.length + \')\';\n            } else {\n                let diffs = 0;\n                for (let k = 0; k < now.length; k++) if (now[k] !== was[k]) diffs++;\n                // Most residues after the first change differ: the frame moved.\n                if (diffs >= 2 && diffs >= 0.6 * (now.length - i)) summary = \'frameshift from residue \' + pos + \' (\' + was[i] + pos + now[i] + \'fs)\';\n                else summary = was[i] + pos + now[i] + (diffs > 1 ? \' and \' + (diffs - 1) + \' more\' : \'\');\n            }\n        } else if (was && now && was === now) {\n            summary = \'no change to the protein\';\n        }\n        try {\n            if (graph && graph.setMessage && summary) graph.setMessage(\' Peptide re-translated: \' + summary + \'. \', 6);\n        } catch (e) { }\n        return { changed: !!(was && now && was !== now), before: was, after: now, summary };\n    })();\n}\n'}
MARK = 'refresh-orf-after-mutation.js'
root = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/baja-apps')
plan = []
for rel, hunks in OPS.items():
    p = os.path.join(root, rel)
    if not os.path.isfile(p):
        sys.exit('Not found: ' + p + '. Nothing was changed.')
    s = open(p, encoding='utf-8').read()
    crlf = '\r\n' in s
    s = s.replace('\r\n', '\n')
    if MARK in s:
        print('Already installed:', p); continue
    for old, new in hunks:
        if s.count(old) != 1:
            sys.exit(p + ' differs from the version this update was made against. Nothing was changed.')
        s = s.replace(old, new, 1)
    plan.append((p, s, crlf))
for rel, text in MODULES.items():
    m = os.path.join(root, rel)
    os.makedirs(os.path.dirname(m), exist_ok=True)
    open(m, 'w', encoding='utf-8').write(text)
    print('Wrote', m)
for p, s, crlf in plan:
    shutil.copyfile(p, p + '.before-mutate-reorf')
    open(p, 'w', encoding='utf-8', newline='').write(s.replace('\n', '\r\n') if crlf else s)
    print('Updated', p)
print('Restart baja-server (it caches scripts), then hard-refresh the editor (Ctrl+Shift+R).')
